  html+=`<div class="group-head">Container queries</div><div class="research-toolbar"><button id="add-container-rule">+ Rule</button></div>${(n.containerRules||[]).map((r,i)=>`<div class="container-card" data-ci="${i}"><div class="mini-grid"><label>Min width</label><input data-ck="minWidth" value="${htmlEsc(r.minWidth||'')}" placeholder="320px"><label>Max width</label><input data-ck="maxWidth" value="${htmlEsc(r.maxWidth||'')}" placeholder="600px"><label>Container name</label><input data-ck="containerName" value="${htmlEsc(r.containerName||'')}"><label>Style JSON</label><input data-ck="style" value="${htmlEsc(JSON.stringify(r.style||{}))}"></div><button data-del-container="${i}">Delete</button></div>`).join('')}`;
  const anim=ensureAnimation(n);html+=`<div class="group-head">Animation</div><div class="research-card"><strong>${anim.tracks.length} track${anim.tracks.length===1?'':'s'}</strong><div class="meta">${htmlEsc(anim.trigger)} · ${htmlEsc(resolveAnimationEngine(anim).toUpperCase())} · ${anim.duration} ms</div><button id="open-animation-editor">Open full Animation Editor</button></div>`;
