  $('#add-node-state').onclick=()=>mutate('Add node state',()=>createNodeState(n,`state${n.states.length+1}`));$('#active-node-state').onchange=e=>mutate('Set node state',()=>n.componentState=e.target.value,{full:false});c.querySelectorAll('[data-si]').forEach(card=>{const st=n.states[Number(card.dataset.si)];card.querySelectorAll('[data-sk]').forEach(el=>el.onchange=()=>mutate('Edit node state',()=>{if(el.dataset.sk==='style'||el.dataset.sk==='props')st[el.dataset.sk]=parseJsonObject(el.value);else st[el.dataset.sk]=el.value},{full:false}))});c.querySelectorAll('[data-del-state]').forEach(b=>b.onclick=()=>mutate('Delete node state',()=>n.states.splice(Number(b.dataset.delState),1)));
