function ensureDoc(){if(state.doc.kind==='page'&&!state.project.pages.some(x=>x.id===state.doc.id)){state.doc={kind:'page',id:state.project.pages[0]?.id};} if(state.doc.kind==='component'&&!state.project.components.some(x=>x.id===state.doc.id)){state.doc={kind:'page',id:state.project.pages[0]?.id};} const r=root(); if(!findNode(r,state.selectedId))state.selectedId=r.id; if(!currentBreakpoints().some(x=>x.id===state.breakpoint))state.breakpoint='base';}

function mutate(label,fn,{full=true}={}){snapshot(label);try{fn();state.issues=validateProject(state.project);scheduleRecovery();if(full)renderAll();else{renderCanvas();renderRight();renderBottom();renderStatus();}}catch(e){log(`ERROR: ${e.message}`);alert(e.message);undo();}}

