function renderComponentDefinitionInto(el,def,instance){
  const assigned=instance.children||[];
  function r(n){if(n.type==='slot'){const name=n.props.name||'';const matches=assigned.filter(c=>(c.meta?.slot||'')===name);const holder=document.createElement('div');holder.className='slot-preview';holder.style.minHeight='28px';holder.style.padding='4px';if(matches.length)for(const c of matches)holder.appendChild(renderNode(c,true));else if(n.children?.length)for(const c of n.children)holder.appendChild(renderNode(c,true));else holder.textContent=`slot${name?`:${name}`:''}`;return holder;}const x=createElementForNode(n,true);for(const c of n.children||[])x.appendChild(r(c));return x;}
  const preview=r(def.root);preview.style.pointerEvents='none';el.appendChild(preview);
}
function renderNode(node,previewOnly=false){const el=createElementForNode(node,previewOnly);
  if(node.type==='componentInstance'){const d=state.project.components.find(c=>c.id===node.props.definitionId);if(d)renderComponentDefinitionInto(el,d,node);else el.append(`Missing component: ${node.props.definitionId}`);return el}
  if(!['heading','text','badge','button','link','image','input','textarea','select','checkbox','radio','divider','spacer','list','video','icon','island','svgPath','rawSvg','shapeRect','shapeEllipse'].includes(node.type)){
    for(const c of node.children||[])el.appendChild(renderNode(c,previewOnly));
    if(canAcceptChildren(node)&&!(node.children||[]).length&&state.mode==='design'&&!previewOnly){const empty=document.createElement('div');const isRoot=node.id===root().id;empty.className=isRoot?'drop-empty drop-empty-root':'drop-empty';if(isRoot){empty.innerHTML='<div class="empty-state-mark">+</div><strong>Start this page</strong><span>Drag a component from the Palette, double-click one, or choose a starting layout.</span><div class="empty-state-actions"><button data-quick-add="section">Add Section</button><button data-quick-add="container">Add Container</button><button data-quick-add="freeform">Freeform / HMI</button></div>';empty.querySelectorAll('[data-quick-add]').forEach(b=>{b.onpointerdown=e=>e.stopPropagation();b.onclick=e=>{e.stopPropagation();insertPaletteType(b.dataset.quickAdd,node.id)}})}else empty.innerHTML='<span class="drop-empty-plus">+</span><span>Drop here or double-click a component</span>';el.appendChild(empty)}
  }
  if(state.doc.kind==='component'&&node.type==='slot'&&!node.children?.length){const x=document.createElement('div');x.className='drop-empty';x.textContent=`Slot: ${node.props.name||'default'}`;el.appendChild(x)}
  return el;
}

function syncManualCanvasControls(){const cfg=manualSettings(),design=state.mode==='design';const set=(id,on,disabled=!design)=>{const b=$(id);if(!b)return;b.classList.toggle('active',Boolean(on));b.disabled=disabled};set('#manual-rulers-btn',cfg.rulers);set('#manual-snap-btn',cfg.snapEnabled);set('#manual-spacing-btn',cfg.showSpacing);set('#manual-tools-btn',state.bottomTab==='manual'&&state.bottomExpanded,false)}
function renderCanvas(){const art=$('#artboard');art.innerHTML='';ensureManualLayoutProject(state.project);art.classList.toggle('preview-mode',state.mode==='preview');const width=state.auditWidth||bp().width||1280; const tokens=activeTheme()?.tokens||{}; for(const [k,v] of Object.entries(tokens)) art.style.setProperty(`--${k}`,v); art.style.width=`${width}px`;art.style.transform=`scale(${state.zoom})`;art.style.marginBottom=`${Math.max(0,(state.zoom-1)*500)}px`;art.appendChild(renderNode(root()));if(state.mode==='design'){renderRulersAndGuides();renderGridEditOverlay();renderSmartSpacingHandles();renderFlowGapHandles();renderSnapFeedback()}$('#viewport-label').textContent=`${state.auditWidth?'Audit width':bp().label} · ${width}px · ${currentLocale().toUpperCase()}`;$('#zoom-label').textContent=`${Math.round(state.zoom*100)}%`;bindCanvasEvents();syncManualCanvasControls();}
function bindPreviewAnimation(node,el){const a=ensureAnimation(node);if(!a.tracks.length)return;const make=()=>{const x=el.animate(compiledKeyframes(a),animationOptions(a));x.playbackRate=Number(a.playbackRate)||1;el.__uiPreviewAnimation=x;return x};const stop=()=>{try{el.__uiPreviewAnimation?.cancel()}catch{}el.__uiPreviewAnimation=null};if(a.trigger==='load')make();else if(a.trigger==='hover'){el.addEventListener('pointerenter',()=>{stop();make()});el.addEventListener('pointerleave',stop)}else if(a.trigger==='focus'){el.addEventListener('focusin',()=>{stop();make()});el.addEventListener('focusout',stop)}else if(a.trigger==='click')el.addEventListener('click',()=>{stop();make()});else if(a.trigger==='inView'){const io=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting)){stop();make()}},{root:$('#artboard-shell'),threshold:.15});io.observe(el)}else if(a.trigger==='scroll'){const shell=$('#artboard-shell');let player=make();player.pause();const update=()=>{const r=el.getBoundingClientRect(),vr=shell.getBoundingClientRect(),span=vr.height+r.height,p=Math.max(0,Math.min(1,(vr.bottom-r.top)/span));player.currentTime=p*a.duration};shell.addEventListener('scroll',update,{passive:true});update()}}
function bindCanvasEvents(){const art=$('#artboard');
  art.querySelectorAll('[data-node-id]').forEach(el=>{
    const id=el.dataset.nodeId;const node=findNode(root(),id);if(!node)return;
    if(state.mode==='design'){el.addEventListener('pointerdown',e=>{e.stopPropagation();const multi=e.ctrlKey||e.metaKey||e.shiftKey;if(multi){state.multiSelected??=new Set();if(state.multiSelected.size===0&&state.selectedId&&state.selectedId!==root().id)state.multiSelected.add(state.selectedId);if(state.multiSelected.has(id)){state.multiSelected.delete(id);if(state.selectedId===id)state.selectedId=[...state.multiSelected][0]||root().id}else{state.multiSelected.add(id);state.selectedId=id}renderCanvas();renderRight();renderBottom();renderStatus();return}state.multiSelected?.clear();state.selectedId=id;el.classList.add('selected');renderRight();renderBottom();renderStatus();if(!node.meta?.locked&&canEditDomain(node,'structure')&&manualMovable(node)){el.draggable=false;beginManualDrag(e,node,el)}else renderCanvas()});el.addEventListener('pointerenter',()=>{state.manual.hoverId=id;if(state.manual.altDown)renderManualTransient()});el.addEventListener('pointerleave',()=>{if(state.manual.hoverId===id)state.manual.hoverId=null;if(state.manual.altDown)renderManualTransient()});if(node.type!=='page'&&!node.meta?.locked&&canEditDomain(node,'structure')&&!manualMovable(node)){el.draggable=true;el.addEventListener('dragstart',e=>{e.stopPropagation();e.dataTransfer.setData('application/x-designer-node',id);e.dataTransfer.effectAllowed='move'})}}
    el.oncontextmenu=e=>showNodeContextMenu(e,node);
    el.querySelectorAll(':scope > .resize-handle').forEach(h=>{if(state.mode==='design'&&!node.meta?.locked&&canEditDomain(node,'style'))h.onpointerdown=e=>beginManualResize(e,node,h.dataset.handle||'se')});const rot=el.querySelector(':scope > .rotate-handle');if(rot&&state.mode==='design'&&!node.meta?.locked&&canEditDomain(node,'style'))rot.onpointerdown=e=>beginManualRotate(e,node);
    if(state.mode==='preview'){bindPreviewAnimation(node,el);for(const ev of new Set((node.actions||[]).map(a=>mapPreviewEvent(a.event))))el.addEventListener(ev,e=>runPreviewActions(node,e));bindPreviewPrototype(node,el);}
    if(canAcceptChildren(node)&&state.mode==='design'&&canEditDomain(node,'structure')){el.addEventListener('dragover',e=>{e.preventDefault();e.stopPropagation();el.classList.add('drop-target')});el.addEventListener('dragleave',e=>{if(!el.contains(e.relatedTarget))el.classList.remove('drop-target')});el.addEventListener('drop',e=>{e.preventDefault();e.stopPropagation();el.classList.remove('drop-target');handleDrop(node,e)})}
  });
  $('#artboard-shell').onpointerdown=e=>{if(e.target===e.currentTarget&&state.mode==='design'){state.multiSelected?.clear();state.selectedId=root().id;renderCanvas();renderRight();renderBottom();renderStatus()}};
}
function mapPreviewEvent(ev){return ev==='focus'?'focusin':ev==='blur'?'focusout':ev}
function bindPreviewPrototype(node,el){for(const i of node.design?.interactions||[]){const fire=e=>runPreviewPrototype(i,e,el);if(i.trigger==='click')el.addEventListener('click',fire);else if(i.trigger==='mouseenter')el.addEventListener('pointerenter',fire);else if(i.trigger==='mouseleave')el.addEventListener('pointerleave',fire);else if(i.trigger==='delay')setTimeout(()=>fire(new Event('ui-delay')),Math.max(0,Number(i.delay)||0));}}
function runPreviewPrototype(i,event,source){const targetEl=i.destination?$('#artboard').querySelector(`[data-node-id="${CSS.escape(i.destination)}"]`):null;switch(i.action){case'navigate':{const page=state.project.pages.find(p=>p.id===i.destination);log(`[preview] prototype navigate → ${page?.route||i.url||i.destination||'/'}`);event.preventDefault?.();break}case'openOverlay':if(targetEl){targetEl.hidden=false;targetEl.dataset.prototypeOverlay='open';targetEl.style.zIndex='999';}break;case'toggleOverlay':if(targetEl){const open=targetEl.dataset.prototypeOverlay==='open';targetEl.hidden=open;if(open)delete targetEl.dataset.prototypeOverlay;else targetEl.dataset.prototypeOverlay='open';}break;case'closeOverlay':{const t=targetEl||source.closest('[data-prototype-overlay="open"]');if(t){t.hidden=true;delete t.dataset.prototypeOverlay}}break;case'previous':log('[preview] prototype previous');break;case'openUrl':log(`[preview] open URL → ${i.url||''}`);event.preventDefault?.();break;}}
function handleDrop(parent,e){if(parent.meta?.locked)return;const type=e.dataTransfer.getData('application/x-designer-type');const assetId=e.dataTransfer.getData('application/x-designer-asset');const componentId=e.dataTransfer.getData('application/x-designer-component');const moving=e.dataTransfer.getData('application/x-designer-node');
  if(moving){if(moving===parent.id||findNode(findNode(root(),moving),parent.id))return;mutate('Move object',()=>{const old=findParent(root(),moving);const n=removeNode(root(),moving);if(!n)return;if(COMPONENTS[parent.type]?.freeformChildren){const rect=e.currentTarget.getBoundingClientRect();const grid=Number(state.project.settings.gridSize)||8;const sx=v=>Math.max(0,Math.round(v/grid)*grid);n.style.base={...(n.style.base||{}),position:'absolute',left:`${sx((e.clientX-rect.left)/state.zoom)}px`,top:`${sx((e.clientY-rect.top)/state.zoom)}px`,width:n.style.base?.width||'220px'}}parent.children.push(n);state.multiSelected?.clear();state.selectedId=n.id});return}
  if(assetId){const a=state.project.assets.find(x=>x.id===assetId);if(!a)return;const n=createNode(a.mime?.startsWith('image/')?'image':'link',{props:a.mime?.startsWith('image/')?{src:`asset:${a.id}`,alt:a.name}:{text:a.name,href:`asset:${a.id}`}});dropInsert(parent,n,e);return}
  if(componentId){const d=state.project.components.find(x=>x.id===componentId);if(!d)return;dropInsert(parent,createNode('componentInstance',{name:`${d.name}Instance`,props:{definitionId:d.id,propValues:{}}}),e);return}
  if(type){const spec=COMPONENTS[type];if(spec?.componentDefinitionOnly&&state.doc.kind!=='component'){log(`${spec.label} can only be used inside component definitions.`);return}const n=createNode(type);dropInsert(parent,n,e)}
}
function dropInsert(parent,n,e){mutate(`Add ${n.type}`,()=>{if(COMPONENTS[parent.type]?.freeformChildren){const rect=e.currentTarget.getBoundingClientRect();n.style.base={...(n.style.base||{}),position:'absolute',left:`${Math.max(0,Math.round((e.clientX-rect.left)/state.zoom))}px`,top:`${Math.max(0,Math.round((e.clientY-rect.top)/state.zoom))}px`,width:n.style.base?.width||'220px'};}parent.children.push(n);state.selectedId=n.id})}
function runPreviewActions(node,event){if(state.testRecording){addTestStep(state.testRecording,event.type,node.id,'');state.dirty=true;if(state.bottomTab==='tests')renderBottom();}for(const a of node.actions||[]){if(mapPreviewEvent(a.event)!==event.type)continue;if(a.condition&&!previewCondition(a.condition))continue;const targetEl=a.target?$('#artboard').querySelector(`[data-node-id="${CSS.escape(a.target)}"]`):null;const value=interpolate(a.value||'');switch(a.type){case'navigate':event.preventDefault();log(`[preview] navigate → ${value}`);break;case'openUrl':event.preventDefault();log(`[preview] open URL → ${value}`);break;case'previous':log('[preview] history previous');break;case'openOverlay':if(targetEl){targetEl.hidden=false;targetEl.dataset.prototypeOverlay='open';}break;case'toggleOverlay':if(targetEl){const open=targetEl.dataset.prototypeOverlay==='open';targetEl.hidden=open;if(open)delete targetEl.dataset.prototypeOverlay;else targetEl.dataset.prototypeOverlay='open';}break;case'closeOverlay':if(targetEl){targetEl.hidden=true;delete targetEl.dataset.prototypeOverlay;}break;case'show':if(targetEl)targetEl.hidden=false;break;case'hide':if(targetEl)targetEl.hidden=true;break;case'toggleClass':targetEl?.classList.toggle(value||'active');break;case'scrollTo':targetEl?.scrollIntoView({behavior:'smooth',block:'center'});break;case'setText':if(targetEl)targetEl.textContent=value;break;case'setState':{const i=value.indexOf('=');if(i>0){const k=value.slice(0,i).trim();state.previewState[k]=parseScalar(value.slice(i+1).trim());renderCanvas();renderBottom()}break}case'toggleState':state.previewState[value]=!state.previewState[value];renderCanvas();renderBottom();break;case'emit':log(`[preview] custom event: ${value}`);break;case'invokeGlobalAction':{const [ctxName,actionName]=String(value).split('.');const ctx=state.project.composition?.globalContexts?.find(x=>x.name===ctxName);const act=ctx?.actions?.find(x=>x.name===actionName);log(act?`[preview] global action: ${ctxName}.${actionName}`:`[preview] missing global action: ${value}`);break;}case'submit':log('[preview] form submit');event.preventDefault();break;case'setComponentState':if(targetEl){const tn=findNode(root(),a.target);targetEl.dataset.uiState=value||'default';const st=tn?.states?.find(x=>x.name===(value||'default'));if(st)Object.assign(targetEl.style,st.style||{});}break;case'playAnimation':case'startTimeline':previewActionAnimation(a.target,'play',value);break;case'pauseAnimation':previewActionAnimation(a.target,'pause',value);break;case'stopAnimation':case'stopTimeline':previewActionAnimation(a.target,'stop',value);break;case'reverseAnimation':previewActionAnimation(a.target,'reverse',value);break;case'seekAnimation':previewActionAnimation(a.target,'seek',value);break;}}}
function parseScalar(v){if(v==='true')return true;if(v==='false')return false;if(v!==''&&!Number.isNaN(Number(v)))return Number(v);return v.replace(/^['"]|['"]$/g,'')}
function interpolate(v){return String(v).replace(/\{\{state\.([A-Za-z_$][\w$]*)\}\}/g,(_,k)=>String(state.previewState[k]??''))}
function previewCondition(c){return evaluateExpression(c,{state:state.previewState,props:selected()?.props||{},data:{},locale:currentLocale()})}

function renderBreakpoints(){const sel=$('#breakpoint-select');sel.innerHTML=currentBreakpoints().map(x=>`<option value="${htmlEsc(x.id)}" ${x.id===state.breakpoint?'selected':''}>${htmlEsc(x.label)} · ${x.width}px</option>`).join('');sel.onchange=()=>{state.breakpoint=sel.value;state.auditWidth=null;renderCanvas();renderRight();renderStatus()}}
function renderDocTabs(){const el=$('#doc-tabs');const tabs=[...state.project.pages.map(p=>({kind:'page',id:p.id,label:`${p.name} · ${p.route}`})),...state.project.components.map(c=>({kind:'component',id:c.id,label:`◇ ${c.name}`}))];el.innerHTML=tabs.map(t=>`<button class="doc-tab ${state.doc.kind===t.kind&&state.doc.id===t.id?'active':''}" data-kind="${t.kind}" data-id="${t.id}">${htmlEsc(t.label)}</button>`).join('');el.querySelectorAll('button').forEach(b=>b.onclick=()=>openDoc(b.dataset.kind,b.dataset.id))}
function openDoc(kind,id,nodeId=null){state.doc={kind,id};ensureDoc();state.multiSelected?.clear();state.selectedId=nodeId||root().id;renderAll()}

function renderLeft(){const c=$('#left-content');if(state.leftTab==='palette')renderPalette(c);else if(state.leftTab==='project')renderProjectPanel(c);else if(state.leftTab==='components')renderComponentsPanel(c);else if(state.leftTab==='assets')renderAssetsPanel(c);else renderSourcesPanel(c)}
function renderPalette(c){const groups={};for(const [type,s] of Object.entries(COMPONENTS)){if(s.paletteHidden)continue;if(s.componentDefinitionOnly&&state.doc.kind!=='component')continue;if(state.paletteFilter&&!`${s.label} ${s.category}`.toLowerCase().includes(state.paletteFilter.toLowerCase()))continue;(groups[s.category]??=[]).push({type,s})}
  c.innerHTML=`<input class="search" id="palette-search" placeholder="Filter components…  /" aria-label="Filter components" value="${htmlEsc(state.paletteFilter)}">`+Object.entries(groups).map(([g,items])=>{const key=`palette:${g}`,closed=state.collapsed.has(key)&&!state.paletteFilter;return `<button class="group-head palette-group-head" data-palette-group="${htmlEsc(g)}" aria-expanded="${closed?'false':'true'}"><span class="palette-group-chevron">${closed?'›':'⌄'}</span><span>${htmlEsc(g)}</span><span class="palette-group-count">${items.length}</span></button><div class="palette-grid ${closed?'palette-group-collapsed':''}" data-palette-body="${htmlEsc(g)}">${items.map(({type,s})=>`<div class="palette-item" title="${htmlEsc(s.label)} · double-click or press Enter to insert" draggable="true" data-type="${type}"><span class="palette-icon">${htmlEsc(s.icon||type.slice(0,2))}</span><span class="palette-label">${htmlEsc(s.label)}</span></div>`).join('')}</div>`}).join('');
  $('#palette-search').oninput=e=>{state.paletteFilter=e.target.value;renderLeft()};c.querySelectorAll('[data-palette-group]').forEach(x=>x.onclick=()=>{const key=`palette:${x.dataset.paletteGroup}`;state.collapsed.has(key)?state.collapsed.delete(key):state.collapsed.add(key);renderLeft()});c.querySelectorAll('.palette-item').forEach(x=>{x.tabIndex=0;x.ondragstart=e=>{e.dataTransfer.setData('application/x-designer-type',x.dataset.type);e.dataTransfer.effectAllowed='copy'};x.ondblclick=()=>insertPaletteType(x.dataset.type);x.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();insertPaletteType(x.dataset.type)}}})}
function renderProjectPanel(c){c.innerHTML=`<div class="left-actions"><button id="add-page">+ Page</button><button id="project-settings">Settings</button></div><div class="group-head">Pages / Routes</div>${state.project.pages.map(p=>`<div class="project-row ${state.doc.kind==='page'&&state.doc.id===p.id?'selected':''}" data-id="${p.id}"><span>▤</span><span>${htmlEsc(p.name)} <small>${htmlEsc(p.route)}</small></span><span class="row-actions"><button data-edit="${p.id}">✎</button><button data-copy="${p.id}">⧉</button><button data-del="${p.id}">×</button></span></div>`).join('')}<div class="group-head">Project</div><div class="project-row"><span>◆</span><span>${htmlEsc(state.project.name)}</span><span></span></div>`;c.querySelectorAll('.project-row[data-id]').forEach(r=>r.onclick=e=>{if(e.target.tagName!=='BUTTON')openDoc('page',r.dataset.id)});$('#add-page').onclick=()=>editPage();$('#project-settings').onclick=projectSettings;c.querySelectorAll('[data-edit]').forEach(b=>b.onclick=e=>{e.stopPropagation();editPage(b.dataset.edit)});c.querySelectorAll('[data-copy]').forEach(b=>b.onclick=e=>{e.stopPropagation();duplicatePage(b.dataset.copy)});c.querySelectorAll('[data-del]').forEach(b=>b.onclick=e=>{e.stopPropagation();deletePage(b.dataset.del)})}
function renderComponentsPanel(c){c.innerHTML=`<div class="left-actions"><button id="new-component">+ Blank</button><button id="from-selection">From Selection</button></div><div class="group-head">Project Components</div>${state.project.components.length?state.project.components.map(x=>`<div class="component-row ${state.doc.kind==='component'&&state.doc.id===x.id?'selected':''}" data-id="${x.id}"><span>◇</span><span>${htmlEsc(x.name)} <small>${htmlEsc(x.filename)}</small></span><span class="row-actions"><button data-ins="${x.id}" title="Insert into current container">＋</button><button data-ren="${x.id}">✎</button><button data-del="${x.id}">×</button></span></div>`).join(''):'<div class="empty">No reusable components yet.</div>'}`;$('#new-component').onclick=createBlankComponent;$('#from-selection').onclick=createComponentFromSelection;c.querySelectorAll('.component-row').forEach(r=>{r.draggable=true;r.ondragstart=e=>{e.dataTransfer.setData('application/x-designer-component',r.dataset.id);e.dataTransfer.effectAllowed='copy'};r.ondblclick=e=>{if(e.target.tagName!=='BUTTON')insertReusableComponent(r.dataset.id)};r.onclick=e=>{if(e.target.tagName!=='BUTTON')openDoc('component',r.dataset.id)}});c.querySelectorAll('[data-ins]').forEach(b=>b.onclick=e=>{e.stopPropagation();insertReusableComponent(b.dataset.ins)});c.querySelectorAll('[data-ren]').forEach(b=>b.onclick=e=>{e.stopPropagation();renameComponent(b.dataset.ren)});c.querySelectorAll('[data-del]').forEach(b=>b.onclick=e=>{e.stopPropagation();deleteComponent(b.dataset.del)})}
function renderAssetsPanel(c){c.innerHTML=`<div class="left-actions"><button id="add-assets">+ Import</button></div><div class="group-head">Assets</div>${state.project.assets.length?state.project.assets.map(a=>`<div class="asset-row" draggable="true" data-id="${a.id}">${a.mime?.startsWith('image/')?`<img class="asset-thumb" src="${a.dataUrl}">`:'<span>▧</span>'}<span>${htmlEsc(a.name)} <small>${formatBytes(a.size)}</small></span><span class="row-actions"><button data-copyref="${a.id}">Ref</button><button data-del="${a.id}">×</button></span></div>`).join(''):'<div class="empty">Import images, fonts, media or other public assets.</div>'}`;$('#add-assets').onclick=()=>$('#asset-open').click();c.querySelectorAll('.asset-row').forEach(r=>r.ondragstart=e=>{e.dataTransfer.setData('application/x-designer-asset',r.dataset.id);e.dataTransfer.effectAllowed='copy'});c.querySelectorAll('[data-copyref]').forEach(b=>b.onclick=()=>navigator.clipboard?.writeText(`asset:${b.dataset.copyref}`));c.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>mutate('Delete asset',()=>{state.project.assets=state.project.assets.filter(a=>a.id!==b.dataset.del)}))}
function formatBytes(n=0){return n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`}

function fieldHtml(f,val,idPrefix='p'){const id=`${idPrefix}-${f.key}`;if(f.kind==='select')return `<select id="${id}">${f.options.map(o=>`<option ${String(val)===String(o)?'selected':''}>${htmlEsc(o)}</option>`).join('')}</select>`;if(f.kind==='checkbox')return `<div class="check-cell"><input id="${id}" type="checkbox" ${val?'checked':''}></div>`;if(f.kind==='textarea')return `<textarea id="${id}">${htmlEsc(val??'')}</textarea>`;if(f.kind!=='number'&&shouldOfferColorPicker(f.key,'',f.label))return colorAwareInput(id,val,f.key,f.label);return `<input id="${id}" type="${f.kind==='number'?'number':'text'}" value="${htmlEsc(val??'')}">`}
