function renderProperties(c,n){const multi=(state.multiSelected?.size||0)>1?`<div class="multi-selection-hint">${state.multiSelected.size} objects selected · editing ${htmlEsc(n.name)}</div>`:'';const spec=COMPONENTS[n.type]||{fields:[]};let general=`<div class="property-row"><label>Name</label><input id="obj-name" value="${htmlEsc(n.name)}"></div><div class="property-row"><label>Type</label><span>${htmlEsc(spec.label||n.type)}</span></div><div class="property-row"><label>DOM id</label><input id="obj-domid" value="${htmlEsc(n.meta?.domId||'')}"></div><div class="property-row"><label>CSS classes</label><input id="obj-classes" value="${htmlEsc(n.meta?.className||'')}"></div><div class="property-row"><label>Slot assignment</label><input id="obj-slot" value="${htmlEsc(n.meta?.slot||'')}" placeholder="default = blank"></div><div class="property-row"><label>ARIA label</label><input id="obj-aria" value="${htmlEsc(n.meta?.ariaLabel||'')}"></div><div class="property-row"><label>Role</label><input id="obj-role" value="${htmlEsc(n.meta?.role||'')}"></div><div class="property-row"><label>Tooltip</label><input id="obj-title" value="${htmlEsc(n.meta?.title||'')}"></div><div class="property-row"><label>Tab index</label><input id="obj-tabindex" type="number" value="${htmlEsc(n.meta?.tabIndex??'')}"></div><div class="property-row"><label>Locked</label><div class="check-cell"><input id="obj-locked" type="checkbox" ${n.meta?.locked?'checked':''}></div></div><div class="property-row"><label>Hidden</label><div class="check-cell"><input id="obj-hidden" type="checkbox" ${n.meta?.hidden?'checked':''}></div></div>`;
  if(n.type==='componentInstance'){ const def=state.project.components.find(d=>d.id===n.props.definitionId); general+=`<div class="property-row"><label>Definition</label><select id="component-definition">${state.project.components.map(d=>`<option value="${d.id}" ${d.id===n.props.definitionId?'selected':''}>${htmlEsc(d.name)}</option>`).join('')}</select></div>`; if(def) for(const cp of def.props||[]){const v=n.props.propValues?.[cp.name]??cp.default??'',input=shouldOfferColorPicker('',v,cp.name)?colorCodeControl({value:v,property:colorPropertyHint(cp.name,v),name:cp.name,textAttrs:`data-component-prop="${htmlEsc(cp.name)}"`,pickerTitle:`Pick ${cp.name}`}):`<input data-component-prop="${htmlEsc(cp.name)}" value="${htmlEsc(v)}">`;general+=`<div class="property-row"><label>Prop: ${htmlEsc(cp.name)}</label>${input}</div>`;} }
  let props=(spec.fields||[]).map(f=>`<div class="property-row"><label>${htmlEsc(f.label)}</label>${fieldHtml(f,n.props?.[f.key])}</div>`).join('');
  let externalApi=''; if(n.type==='externalComponent'){const ext=state.project.workspace?.externalComponents?.find(x=>x.id===n.props?.descriptorId);if(ext){normalizeCodeComponentContract(ext);let vals={};try{vals=JSON.parse(n.props.propsJson||'{}')}catch{}const rows=(ext.contract.props||[]).map(cp=>{const v=vals[cp.name]??cp.default??'';let input='';if(cp.type==='boolean')input=`<input data-external-prop="${htmlEsc(cp.name)}" data-external-type="boolean" type="checkbox" ${v?'checked':''}>`;else if(cp.type==='enum'&&cp.options?.length)input=`<select data-external-prop="${htmlEsc(cp.name)}" data-external-type="enum">${cp.options.map(o=>`<option ${String(o)===String(v)?'selected':''}>${htmlEsc(o)}</option>`).join('')}</select>`;else if(['object','list'].includes(cp.type))input=`<textarea data-external-prop="${htmlEsc(cp.name)}" data-external-type="${cp.type}">${htmlEsc(typeof v==='string'?v:JSON.stringify(v,null,2))}</textarea>`;else input=shouldOfferColorPicker('',v,cp.name)?colorCodeControl({value:v,property:colorPropertyHint(cp.name,v),name:cp.name,textAttrs:`data-external-prop="${htmlEsc(cp.name)}" data-external-type="${htmlEsc(cp.type||'string')}"`,pickerTitle:`Pick ${cp.name}`}):`<input data-external-prop="${htmlEsc(cp.name)}" data-external-type="${htmlEsc(cp.type||'string')}" value="${htmlEsc(v)}">`;return `<div class="property-row"><label>${htmlEsc(cp.name)}${cp.required?' *':''}</label>${input}</div>`}).join('');externalApi=`<div class="research-card"><strong>${htmlEsc(ext.contract.displayName||ext.name)}</strong><div class="meta">${htmlEsc(ext.contract.description||ext.importPath||'')}</div></div>${rows||'<div class="empty">No registered props.</div>'}`}}
  let componentApi=''; if(state.doc.kind==='component'&&n.id===root().id){ const d=owner(); componentApi=`<div class="property-row"><label>Definition</label><span>${htmlEsc(d.name)}</span></div><div class="property-row"><label>Props</label><span>${(d.props||[]).length} declared</span></div><div class="inspector-toolbar"><button id="manage-component-props">Manage Props</button></div>`; }
  let page='';if(state.doc.kind==='page'&&n.id===root().id){const p=owner();page=`<div class="property-row"><label>Route</label><input id="page-route" value="${htmlEsc(p.route)}"></div><div class="property-row"><label>File</label><input id="page-file" value="${htmlEsc(p.filename)}"></div><div class="property-row"><label>SEO title</label><input id="seo-title" value="${htmlEsc(p.seo?.title||'')}"></div><div class="property-row"><label>Description</label><textarea id="seo-description">${htmlEsc(p.seo?.description||'')}</textarea></div><div class="property-row"><label>Canonical</label><input id="seo-canonical" value="${htmlEsc(p.seo?.canonical||'')}"></div><div class="property-row"><label>OG image</label><input id="seo-og" value="${htmlEsc(p.seo?.ogImage||'')}"></div>`}
  c.innerHTML=multi+`<div class="inspector-title"><strong>${htmlEsc(n.name)}</strong><span>${htmlEsc(n.id)}</span></div>${section('Object',general)}${props?section('Properties',props):''}${page?section('Page / SEO',page):''}${componentApi?section('Component API',componentApi):''}${externalApi?section('Code Component API',externalApi):''}`;
  const bindChange=(sel,label,fn)=>{const el=$(sel);if(el)el.onchange=()=>mutate(label,()=>fn(el))};bindChange('#obj-name','Rename object',el=>n.name=el.value);bindChange('#obj-domid','Set DOM id',el=>n.meta.domId=el.value.trim());bindChange('#obj-classes','Set CSS classes',el=>n.meta.className=el.value.trim());bindChange('#obj-slot','Change slot assignment',el=>n.meta.slot=el.value);bindChange('#obj-aria','Set ARIA label',el=>n.meta.ariaLabel=el.value);bindChange('#obj-role','Set ARIA role',el=>n.meta.role=el.value.trim());bindChange('#obj-title','Set tooltip',el=>n.meta.title=el.value);bindChange('#obj-tabindex','Set tab order',el=>n.meta.tabIndex=el.value===''?'':Number(el.value));bindChange('#obj-locked','Toggle locked',el=>n.meta.locked=el.checked);bindChange('#obj-hidden','Toggle hidden',el=>n.meta.hidden=el.checked);bindChange('#component-definition','Change component definition',el=>{n.props.definitionId=el.value;n.props.propValues={}}); c.querySelectorAll('[data-component-prop]').forEach(el=>el.onchange=()=>mutate(`Set component prop ${el.dataset.componentProp}`,()=>{n.props.propValues??={};n.props.propValues[el.dataset.componentProp]=el.value},{full:false})); if($('#manage-component-props')) $('#manage-component-props').onclick=()=>manageComponentProps(owner().id);
  for(const f of spec.fields||[]){const el=$(`#p-${f.key}`);if(el)el.onchange=()=>mutate(`Set ${f.label}`,()=>n.props[f.key]=f.kind==='checkbox'?el.checked:el.value,{full:false})}
  c.querySelectorAll('[data-external-prop]').forEach(el=>el.onchange=()=>mutate(`Set code prop ${el.dataset.externalProp}`,()=>{let obj={};try{obj=JSON.parse(n.props.propsJson||'{}')}catch{}let v=el.type==='checkbox'?el.checked:el.value;if(['number'].includes(el.dataset.externalType))v=Number(v);if(['object','list'].includes(el.dataset.externalType)){try{v=JSON.parse(v)}catch{}}obj[el.dataset.externalProp]=v;n.props.propsJson=JSON.stringify(obj)},{full:false}));
  if(page){bindChange('#page-route','Change page route',el=>{owner().route=el.value;owner().filename=routeToFilename(el.value)});bindChange('#page-file','Change page filename',el=>owner().filename=el.value);bindChange('#seo-title','Change SEO title',el=>owner().seo.title=el.value);bindChange('#seo-description','Change SEO description',el=>owner().seo.description=el.value);bindChange('#seo-canonical','Change canonical URL',el=>owner().seo.canonical=el.value);bindChange('#seo-og','Change OG image',el=>owner().seo.ogImage=el.value)}bindColorControls(c)
}

