function renderActions(c,n){const spec=COMPONENTS[n.type]||{};const events=spec.events||['click'];c.innerHTML=`<div class="inspector-title"><strong>Actions · ${htmlEsc(n.name)}</strong><span>${n.actions?.length||0}</span></div><div class="hint">Web-native signals/actions. Multiple actions can respond to one event. Conditions may use simple expressions such as <code>state.menuOpen</code>.</div><div class="inspector-toolbar"><button id="add-action">+ Action</button></div><div id="action-list">${(n.actions||[]).map((a,i)=>actionCard(a,i,events)).join('')}</div>`;$('#add-action').onclick=()=>mutate('Add action',()=>{n.actions??=[];n.actions.push({id:makeId('act'),event:events[0]||'click',type:'navigate',target:'',value:'/',condition:''})});c.querySelectorAll('.action-card').forEach(card=>{const i=Number(card.dataset.i);const a=n.actions[i];card.querySelectorAll('[data-key]').forEach(el=>el.onchange=()=>mutate(`Edit action ${el.dataset.key}`,()=>a[el.dataset.key]=el.value,{full:false}));card.querySelector('.remove').onclick=()=>mutate('Remove action',()=>n.actions.splice(i,1))})}
