function cancelAnimationPreview(){const ed=state.animationEditor;if(ed.raf)cancelAnimationFrame(ed.raf);ed.raf=0;try{ed.player?.cancel()}catch{}ed.player=null;}
function syncAnimationPlayheadUi(){const ed=state.animationEditor;const pct=Math.max(0,Math.min(1,Number(ed.playhead)||0));const range=$('#animation-playhead-range');if(range&&document.activeElement!==range)range.value=String(Math.round(pct*1000)/10);const label=$('#animation-time-label');const a=ensureAnimation(selected());if(label)label.textContent=`${Math.round(pct*a.duration)} ms / ${a.duration} ms`;document.querySelectorAll('.animation-playhead').forEach(x=>x.style.left=`calc(178px + ${pct} * (100% - 190px))`)}
function previewAnimation(command='play',value=null){const node=selected(),a=ensureAnimation(node),el=animationTargetElement(node),ed=state.animationEditor;if(!el||!a.tracks.length)return;
  const make=(paused=false)=>{cancelAnimationPreview();const opts={...animationOptions(a)};if(opts.iterations===Infinity&&command!=='play')opts.iterations=1;const player=el.animate(compiledKeyframes(a),opts);player.playbackRate=Number(a.playbackRate)||1;ed.player=player;if(paused)player.pause();return player};
  if(command==='stop'){cancelAnimationPreview();ed.playhead=0;syncAnimationPlayheadUi();return}
  if(command==='seek'){let p=Number(value);if(p>1)p/=100;p=Math.max(0,Math.min(1,p||0));let player=ed.player;if(!player)player=make(true);player.pause();player.currentTime=p*a.duration;ed.playhead=p;syncAnimationPlayheadUi();return}
  let player=ed.player;if(!player)player=make(command==='pause');if(command==='pause'){player.pause();return}if(command==='reverse'){if(player.playState==='idle')player=make(true);if((player.currentTime??0)<=0)player.currentTime=a.duration;player.reverse();}else{if(player.playState==='finished'||player.playState==='idle')player=make(false);else player.play()}
  const tick=()=>{if(!ed.player)return;const t=Number(ed.player.currentTime)||0;ed.playhead=a.duration?Math.max(0,Math.min(1,(t%a.duration)/a.duration)):0;syncAnimationPlayheadUi();if(['running','pending'].includes(ed.player.playState))ed.raf=requestAnimationFrame(tick)};if(ed.raf)cancelAnimationFrame(ed.raf);ed.raf=requestAnimationFrame(tick);
}
